create or replace function public.review_screening_evidence_row(
  target_company uuid,
  target_analysis uuid,
  target_criterion uuid,
  expected_updated_at timestamptz,
  next_status text,
  next_note text default null,
  next_verdict text default null,
  next_missing_info text default null,
  next_question text default null,
  next_evidence jsonb default null
) returns uuid language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := (select auth.uid());
  analysis public.screening_analysis_versions%rowtype;
  row_data public.screening_criterion_results%rowtype;
  effective_verdict text;
  effective_evidence jsonb;
begin
  if actor is null or not private.has_company_access(target_company, true) then
    raise exception 'No write access' using errcode = '42501';
  end if;
  if next_status not in ('unreviewed','accepted','rejected','edited')
    or length(coalesce(next_note,'')) > 10000
    or length(coalesce(next_missing_info,'')) > 4000
    or length(coalesce(next_question,'')) > 4000
    or next_verdict is not null and next_verdict not in ('supported','partial','missing','contradicted')
    then raise exception 'Invalid row review' using errcode = '22023'; end if;

  select * into analysis from public.screening_analysis_versions
  where company_id = target_company and id = target_analysis;
  if not found then raise exception 'Analysis not found' using errcode = '42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('screening:' || analysis.application_id::text, 0));
  select * into analysis from public.screening_analysis_versions
  where company_id = target_company and id = target_analysis for update;
  if not found or analysis.execution_status <> 'completed' or analysis.stale_at is not null
    or private.screening_stale_reason(analysis.id) is not null
    or exists (select 1 from public.screening_analysis_versions later
      where later.company_id = target_company and later.application_id = analysis.application_id
        and later.analysis_version > analysis.analysis_version)
    then raise exception 'Result is not current' using errcode = '55000'; end if;
  select * into row_data from public.screening_criterion_results
  where company_id = target_company and analysis_id = target_analysis and id = target_criterion for update;
  if not found then raise exception 'Criterion not found' using errcode = '42501'; end if;
  if row_data.updated_at is distinct from expected_updated_at
    then raise exception 'Review changed' using errcode = 'PT409'; end if;
  if row_data.verdict is null
    then raise exception 'Legacy results cannot be reviewed as evidence matrix' using errcode = '55000'; end if;
  if next_status <> 'edited' and (next_verdict is not null or next_missing_info is not null
    or next_question is not null or next_evidence is not null)
    then raise exception 'Edits require edited status' using errcode = '22023'; end if;
  effective_verdict := case when next_status = 'edited' then coalesce(next_verdict, row_data.verdict)
    else row_data.verdict end;
  effective_evidence := case when next_status = 'edited' then coalesce(next_evidence, row_data.evidence)
    else row_data.evidence end;
  if not private.screening_valid_evidence(
      analysis.input_cv_text_snapshot, effective_evidence, effective_verdict <> 'missing'
    ) or (effective_verdict = 'missing' and jsonb_array_length(effective_evidence) <> 0)
    then raise exception 'Evidence and verdict mismatch' using errcode = '22023'; end if;
  update public.screening_criterion_results
  set human_status = next_status,
      human_note = nullif(btrim(next_note),''),
      human_verdict = case when next_status = 'edited' then next_verdict else null end,
      human_missing_info = case when next_status = 'edited' then next_missing_info else null end,
      human_suggested_question = case when next_status = 'edited' then next_question else null end,
      human_evidence = case when next_status = 'edited' then next_evidence else null end,
      updated_by = actor, updated_at = clock_timestamp()
  where company_id = target_company and analysis_id = target_analysis and id = target_criterion;
  -- Every substantive row change is a new review revision. An open analysis-level
  -- form then fails its expected_review_version check instead of approving rows
  -- it never showed, and an existing approval falls behind the analysis: the
  -- ranking reports review_inconsistent, the report skips the analysis, a
  -- shortlist snapshot stops being current and the voice source verifier refuses
  -- it, until a human approves again. A note alone is never published: no bump.
  if (row_data.human_status, row_data.human_verdict, row_data.human_missing_info,
      row_data.human_suggested_question, row_data.human_evidence)
    is distinct from (next_status,
      case when next_status = 'edited' then next_verdict end,
      case when next_status = 'edited' then next_missing_info end,
      case when next_status = 'edited' then next_question end,
      case when next_status = 'edited' then next_evidence end)
  then
    update public.screening_analysis_versions
    set latest_review_version = latest_review_version + 1, updated_at = clock_timestamp()
    where company_id = target_company and id = target_analysis;
  end if;
  return target_criterion;
end;
$$;
revoke all on function public.review_screening_evidence_row(uuid,uuid,uuid,timestamptz,text,text,text,text,text,jsonb)
  from public, anon, authenticated, screening_worker;
grant execute on function public.review_screening_evidence_row(uuid,uuid,uuid,timestamptz,text,text,text,text,text,jsonb)
  to authenticated;

create or replace function public.review_screening_result(
  target_analysis uuid,
  expected_review_version integer,
  new_disposition text,
  new_review_note text,
  new_overrides jsonb default '[]'::jsonb
) returns uuid language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := (select auth.uid());
  analysis public.screening_analysis_versions%rowtype;
  review_id uuid;
  override_item jsonb;
  criterion public.screening_criterion_results%rowtype;
  rating text;
  evidence jsonb;
  explanation text;
  detected_stale_reason text;
begin
  if actor is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if expected_review_version is null or expected_review_version < 0
    or new_disposition not in ('approved', 'approved_with_changes', 'needs_reanalysis')
    or length(coalesce(new_review_note, '')) > 10000
    or jsonb_typeof(new_overrides) is distinct from 'array'
    then raise exception 'Invalid review' using errcode = '22023'; end if;

  -- Authorize before taking a lock on tenant data; match start's lock order.
  select * into analysis from public.screening_analysis_versions
    where id = target_analysis;
  if not found or not private.has_company_access(analysis.company_id, true)
    then raise exception 'No write access' using errcode = '42501'; end if;
  perform private.erasure_lock_candidate(candidate_id) from public.applications where id=analysis.application_id;
  perform pg_advisory_xact_lock(hashtextextended('screening:' || analysis.application_id::text, 0));
  select * into analysis from public.screening_analysis_versions
    where id = target_analysis for update;
  if not found or not private.has_company_access(analysis.company_id, true)
    then raise exception 'No write access' using errcode = '42501'; end if;
  if exists (
    select 1 from public.screening_analysis_versions newer
    where newer.company_id = analysis.company_id
      and newer.application_id = analysis.application_id
      and newer.analysis_version > analysis.analysis_version
  ) then raise exception 'Analysis superseded' using errcode = 'PT409'; end if;

  if analysis.execution_status <> 'completed'
    then raise exception 'Only completed results can be reviewed' using errcode = '55000'; end if;

  detected_stale_reason := private.screening_stale_reason(analysis.id);
  if detected_stale_reason is not null and analysis.stale_at is null then
    update public.screening_analysis_versions
      set stale_at = clock_timestamp(), stale_reason = detected_stale_reason,
        updated_at = clock_timestamp()
      where id = analysis.id;
    analysis.stale_at := clock_timestamp();
    analysis.stale_reason := detected_stale_reason;
  end if;
  if analysis.latest_review_version <> expected_review_version
    then raise exception 'Review changed' using errcode = 'PT409'; end if;
  if analysis.stale_at is not null
    and (new_disposition <> 'needs_reanalysis' or jsonb_array_length(new_overrides) <> 0)
    then raise exception 'Stale result requires reanalysis' using errcode = '55000'; end if;
  if (new_disposition = 'approved_with_changes' and jsonb_array_length(new_overrides) = 0)
    or (new_disposition in ('approved', 'needs_reanalysis')
      and jsonb_array_length(new_overrides) <> 0)
    then raise exception 'Overrides do not match disposition' using errcode = '22023'; end if;
  -- Evidence-matrix (v2) analyses: corrections live in the rows and approval
  -- requires a human review of every row. Row reviews take the same advisory lock.
  if exists (select 1 from public.screening_criterion_results r
      where r.company_id = analysis.company_id and r.analysis_id = analysis.id and r.verdict is not null) then
    if new_disposition = 'approved_with_changes' or jsonb_array_length(new_overrides) <> 0
      then raise exception 'Evidence matrix corrections belong to its rows' using errcode = '22023'; end if;
    if new_disposition = 'approved' and exists (select 1 from public.screening_criterion_results r
        where r.company_id = analysis.company_id and r.analysis_id = analysis.id and r.human_status = 'unreviewed')
      then raise exception 'Every evidence matrix row needs a human review' using errcode = '55000'; end if;
  end if;

  for override_item in select value from jsonb_array_elements(new_overrides) loop
    if jsonb_typeof(override_item) is distinct from 'object'
      or exists (
        select 1 from jsonb_object_keys(override_item) key
        where key not in (
          'criterion_result_id', 'rating_override',
          'evidence_override', 'explanation_override'
        )
      )
      or jsonb_typeof(override_item->'criterion_result_id') is distinct from 'string'
      or (override_item ? 'rating_override'
        and jsonb_typeof(override_item->'rating_override') not in ('string', 'null'))
      or (override_item ? 'evidence_override'
        and jsonb_typeof(override_item->'evidence_override') not in ('array', 'null'))
      or (override_item ? 'explanation_override'
        and jsonb_typeof(override_item->'explanation_override') not in ('string', 'null'))
      then raise exception 'Invalid review override' using errcode = '22023'; end if;
    begin
      select * into criterion from public.screening_criterion_results
      where id = (override_item->>'criterion_result_id')::uuid
        and company_id = analysis.company_id and analysis_id = analysis.id;
    exception when invalid_text_representation then
      raise exception 'Invalid criterion reference' using errcode = '22023';
    end;
    if not found then raise exception 'Criterion does not belong to analysis' using errcode = '22023'; end if;
    rating := coalesce(override_item->>'rating_override', criterion.rating);
    evidence := case when override_item ? 'evidence_override'
      and jsonb_typeof(override_item->'evidence_override') <> 'null'
      then override_item->'evidence_override' else criterion.evidence end;
    explanation := override_item->>'explanation_override';
    if not (override_item ? 'rating_override'
      or override_item ? 'evidence_override'
      or override_item ? 'explanation_override')
      or rating not in ('insufficient_data', 'below', 'meets', 'above')
      or length(coalesce(explanation, '')) > 4000
      or not private.screening_valid_evidence(
        analysis.input_cv_text_snapshot, evidence, rating <> 'insufficient_data'
      ) then raise exception 'Invalid review evidence' using errcode = '22023'; end if;
  end loop;
  if (
    select count(distinct value->>'criterion_result_id')
    from jsonb_array_elements(new_overrides)
  ) <> jsonb_array_length(new_overrides)
    then raise exception 'Duplicate review override' using errcode = '22023'; end if;

  insert into public.screening_result_reviews(
    company_id, analysis_id, review_version, reviewer_id,
    disposition, review_note
  ) values (
    analysis.company_id, analysis.id, expected_review_version + 1, actor,
    new_disposition, nullif(btrim(new_review_note), '')
  ) returning id into review_id;

  for override_item in select value from jsonb_array_elements(new_overrides) loop
    insert into public.screening_criterion_review_overrides(
      company_id, review_id, criterion_result_id,
      rating_override, evidence_override, explanation_override
    ) values (
      analysis.company_id,
      review_id,
      (override_item->>'criterion_result_id')::uuid,
      override_item->>'rating_override',
      case when override_item ? 'evidence_override'
        and jsonb_typeof(override_item->'evidence_override') <> 'null'
        then override_item->'evidence_override' else null end,
      override_item->>'explanation_override'
    );
  end loop;
  update public.screening_analysis_versions
    set latest_review_version = expected_review_version + 1,
      updated_at = clock_timestamp()
    where id = analysis.id;
  return review_id;
end;
$$;
revoke all on function public.review_screening_result(uuid,integer,text,text,jsonb)
  from public, anon, authenticated, screening_worker;
grant execute on function public.review_screening_result(uuid,integer,text,text,jsonb)
  to authenticated

-- A recruitment inherits its position from recruitments.position_id.
-- No decision default: only the authenticated explicit RPC can change it.
alter table public.applications
  add column current_stage_id uuid,
  add column human_decision text check (human_decision in ('next_stage', 'on_hold', 'closed')),
  add column human_decision_reason text check (human_decision_reason is null or length(btrim(human_decision_reason)) between 10 and 5000),
  add constraint application_decision_reason_pair check (
    (human_decision is null and human_decision_reason is null)
    or (human_decision is not null and human_decision_reason is not null)
  ),
  add constraint application_current_stage_fk foreign key (company_id, recruitment_id, current_stage_id)
    references public.assessment_stages(company_id, recruitment_id, id) on delete restrict;

-- Legacy API callers have INSERT on applications. A caller cannot inject a
-- stage/decision on creation to bypass the explicit audited RPCs.
create function private.reject_unaudited_application_insert()
returns trigger language plpgsql set search_path = '' as $$
begin
  if new.current_stage_id is not null or new.human_decision is not null
     or new.human_decision_reason is not null then
    raise exception 'Stage and human decision require explicit audited action' using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function private.reject_unaudited_application_insert() from public, anon, authenticated;
create trigger application_manual_fields_insert_guard before insert on public.applications
for each row execute function private.reject_unaudited_application_insert();

-- Existing per-stage candidate_assessments.notes remains the live note.

create table public.application_stage_events (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null,
  recruitment_id uuid not null,
  application_id uuid not null,
  from_stage_id uuid,
  to_stage_id uuid,
  actor_id uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  check (from_stage_id is distinct from to_stage_id),
  foreign key (company_id, recruitment_id, application_id)
    references public.applications(company_id, recruitment_id, id) on delete cascade,
  foreign key (company_id, recruitment_id, from_stage_id)
    references public.assessment_stages(company_id, recruitment_id, id) on delete restrict,
  foreign key (company_id, recruitment_id, to_stage_id)
    references public.assessment_stages(company_id, recruitment_id, id) on delete restrict
);
create index application_stage_events_lookup on public.application_stage_events(company_id, recruitment_id, application_id, created_at desc);

create table public.application_decision_events (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null,
  recruitment_id uuid not null,
  application_id uuid not null,
  previous_decision text check (previous_decision in ('next_stage', 'on_hold', 'closed')),
  new_decision text not null check (new_decision in ('next_stage', 'on_hold', 'closed')),
  reason text not null check (length(btrim(reason)) between 10 and 5000),
  actor_id uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  foreign key (company_id, recruitment_id, application_id)
    references public.applications(company_id, recruitment_id, id) on delete cascade
);
create index application_decision_events_lookup on public.application_decision_events(company_id, recruitment_id, application_id, created_at desc);

-- Append-only revisions, not a competing live-notes table.
create table public.candidate_assessment_note_revisions (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null,
  recruitment_id uuid not null,
  application_id uuid not null,
  assessment_id uuid not null references public.candidate_assessments(id) on delete cascade,
  body text,
  author_id uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  foreign key (company_id, recruitment_id, application_id)
    references public.applications(company_id, recruitment_id, id) on delete cascade
);
create index candidate_note_revisions_lookup on public.candidate_assessment_note_revisions(company_id, recruitment_id, application_id, assessment_id, created_at desc);

do $$
declare tbl text;
begin
  foreach tbl in array array['application_stage_events','application_decision_events','candidate_assessment_note_revisions'] loop
    execute format('alter table public.%I enable row level security',tbl);
    execute format('revoke all on public.%I from public, anon, authenticated',tbl);
    if exists (select 1 from pg_roles where rolname = 'service_role') then
      execute format('revoke all on public.%I from service_role',tbl);
    end if;
    execute format('grant select on public.%I to authenticated',tbl);
    execute format('create policy tenant_read on public.%I for select to authenticated using (private.has_company_access(company_id))',tbl);
  end loop;
end $$;

-- These log tables cannot be written, updated or deleted by an API session.
-- Application stage/decision columns intentionally receive NO UPDATE grants.

create function private.track_candidate_assessment_notes()
returns trigger language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid());
begin
  if tg_op = 'INSERT' then
    if new.notes is null then return new; end if;
  elsif tg_op = 'UPDATE' then
    if new.notes is not distinct from old.notes then return new; end if;
  end if;
  if actor is null or not private.has_company_access(new.company_id, true) then
    raise exception 'Human author required for notes' using errcode = '42501';
  end if;
  insert into public.candidate_assessment_note_revisions(company_id,recruitment_id,application_id,assessment_id,body,author_id)
    values(new.company_id,new.recruitment_id,new.application_id,new.id,new.notes,actor);
  return new;
end $$;
revoke all on function private.track_candidate_assessment_notes() from public, anon, authenticated;
create trigger candidate_assessment_note_history after insert or update on public.candidate_assessments
for each row execute function private.track_candidate_assessment_notes();

-- Concurrency-safe stage reordering across one recruitment. Client never rewrites
-- all sequence numbers, which would collide with the existing unique key.
create function public.move_assessment_stage(target_company uuid, target_recruitment uuid, target_stage uuid, move_direction integer)
returns void language plpgsql security definer set search_path = '' as $$
declare item record; neighbor record; temporary_sequence integer;
begin
  if not private.has_company_access(target_company,true) or move_direction is null or move_direction not in (-1,1) then
    raise exception 'Stage update not allowed' using errcode = '42501';
  end if;
  perform 1 from public.recruitments where company_id=target_company and id=target_recruitment for update;
  if not found then raise exception 'Recruitment not found'; end if;
  select id, sequence into item from public.assessment_stages
    where company_id=target_company and recruitment_id=target_recruitment and id=target_stage;
  if not found then raise exception 'Stage not found'; end if;
  if move_direction = -1 then
    select id,sequence into neighbor from public.assessment_stages
      where company_id=target_company and recruitment_id=target_recruitment and sequence < item.sequence
      order by sequence desc limit 1;
  else
    select id,sequence into neighbor from public.assessment_stages
      where company_id=target_company and recruitment_id=target_recruitment and sequence > item.sequence
      order by sequence limit 1;
  end if;
  if neighbor.id is null then return; end if;
  select coalesce(max(sequence),0)+1 into temporary_sequence from public.assessment_stages
    where company_id=target_company and recruitment_id=target_recruitment;
  update public.assessment_stages set sequence=temporary_sequence where id=item.id and company_id=target_company;
  update public.assessment_stages set sequence=item.sequence where id=neighbor.id and company_id=target_company;
  update public.assessment_stages set sequence=neighbor.sequence where id=item.id and company_id=target_company;
end $$;

create function public.move_application_stage(target_company uuid, target_recruitment uuid, target_application uuid, target_stage uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid()); old_stage uuid;
begin
  if actor is null or not private.has_company_access(target_company,true) then
    raise exception 'Stage change requires authenticated recruiter' using errcode = '42501';
  end if;
  if target_stage is not null and not exists (
    select 1 from public.assessment_stages where company_id=target_company and recruitment_id=target_recruitment and id=target_stage
  ) then raise exception 'Stage outside recruitment'; end if;
  select current_stage_id into old_stage from public.applications
    where company_id=target_company and recruitment_id=target_recruitment and id=target_application for update;
  if not found then raise exception 'Application not found'; end if;
  if old_stage is not distinct from target_stage then return; end if;
  update public.applications set current_stage_id=target_stage
    where company_id=target_company and recruitment_id=target_recruitment and id=target_application;
  insert into public.application_stage_events(company_id,recruitment_id,application_id,from_stage_id,to_stage_id,actor_id)
    values (target_company,target_recruitment,target_application,old_stage,target_stage,actor);
end $$;

create function public.set_application_human_decision(target_company uuid, target_recruitment uuid, target_application uuid, requested_decision text, justification text)
returns void language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid()); old_decision text; clean_reason text := btrim(coalesce(justification,''));
begin
  if actor is null or not private.has_company_access(target_company,true) then
    raise exception 'Human decision requires authenticated recruiter' using errcode = '42501';
  end if;
  if requested_decision is null or requested_decision not in ('next_stage','on_hold','closed')
     or length(clean_reason) not between 10 and 5000 then
    raise exception 'Explicit decision and justification (10–5000 chars) required' using errcode = '22023';
  end if;
  select human_decision into old_decision from public.applications
    where company_id=target_company and recruitment_id=target_recruitment and id=target_application for update;
  if not found then raise exception 'Application not found'; end if;
  update public.applications set human_decision=requested_decision, human_decision_reason=clean_reason
    where company_id=target_company and recruitment_id=target_recruitment and id=target_application;
  insert into public.application_decision_events(company_id,recruitment_id,application_id,previous_decision,new_decision,reason,actor_id)
    values(target_company,target_recruitment,target_application,old_decision,requested_decision,clean_reason,actor);
end $$;

revoke all on function public.move_assessment_stage(uuid,uuid,uuid,integer) from public, anon, authenticated;
revoke all on function public.move_application_stage(uuid,uuid,uuid,uuid) from public, anon, authenticated;
revoke all on function public.set_application_human_decision(uuid,uuid,uuid,text,text) from public, anon, authenticated;
grant execute on function public.move_assessment_stage(uuid,uuid,uuid,integer),
  public.move_application_stage(uuid,uuid,uuid,uuid),
  public.set_application_human_decision(uuid,uuid,uuid,text,text) to authenticated

do $r8_preflight$
declare
  r7_signature text;
  r7_tables text[];
  source text;
  expected text;
  inventory_source text;
  candidates_source text;
  step4_tables text[]:=array['public.application_decision_events','public.application_stage_events','public.candidate_assessment_note_revisions'];
  actual_tables text[];
begin
  if to_regclass('private.erasure_inventory_baseline_r7') is null then
    raise exception 'sc_r8_requires_r7_inventory' using errcode='55000';
  end if;
  if to_regclass('private.erasure_inventory_baseline_r8') is not null then
    raise exception 'sc_r8_already_installed' using errcode='55000';
  end if;
  if to_regclass('public.application_stage_events') is null or to_regclass('public.application_decision_events') is null
    or to_regclass('public.candidate_assessment_note_revisions') is null then
    raise exception 'sc_r8_requires_step4' using errcode='55000';
  end if;
  execute 'select schema_signature,known_tables from private.erasure_inventory_baseline_r7 where singleton'
    into r7_signature,r7_tables;
  -- R7 legacy -> reviewed Step 4 source -> final R8 (including the R8 table
  -- itself); likewise for the voice variant. Anything else is unreviewed.
  case r7_signature
    when '4e14a55722abf0006758a2d439ac41209b41c9a9e4a85e0adebdaa526c7cf5d7' then
      source:='81388d40db8145b5638749b2652e229b55b73901e9905c9de16ddf495825d074';
      inventory_source:='a17cd31da4c1db771ca001524682155239b20856e19f246086f12ad5034acac1';
      candidates_source:='e7733f59150888a88b9adc2c9002ac14af7addbcc5193f1b1404f78e15510421';
      expected:='d87bccd9dcf7834aeed6bd361cb117b1b11f221f2bc0280d852843d29996bdaf';
    when 'f61669ada2303111a5d027a012c8c9d6b0cc0ece4ac52eaefb7a33a40e5942c3' then
      source:='641650aea54f6e013326c76c883766fc303645e6f5f4c19b51676da9ed2e12a6';
      inventory_source:='4a3a148fd8570a0c5df9bacf66458afa0a71069ce5e5637bee235b18b1ce64e3';
      candidates_source:='0feabad0bbfac8aa678f2ca3f10df0428238313fac8dd2c863b61c2319adb1ea';
      expected:='f057e8bce49280b3ec6dfff5259bb9b27174829ba068b1f429b003b8cb61cda9';
    else raise exception 'sc_r8_r7_baseline_unreviewed' using errcode='55000';
  end case;
  if private.erasure_schema_signature() is distinct from source then
    raise exception 'sc_r8_source_schema_unreviewed:%',private.erasure_schema_signature() using errcode='55000';
  end if;
  if (select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_proc where oid='private.erasure_inventory_rows(uuid,uuid[])'::regprocedure) is distinct from inventory_source
    or (select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_proc where oid='private.erasure_row_candidates(text,jsonb)'::regprocedure) is distinct from candidates_source then
    raise exception 'sc_r8_adapter_source_unreviewed' using errcode='55000';
  end if;
  if (select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_proc where oid='private.erasure_guard_parent_row()'::regprocedure)
    is distinct from '9a3868ef8d58ed6942be1d34973c2d3cb9b131d9d0a803cca7900b802e7a5ac6' then
    raise exception 'sc_r8_parent_guard_source_unreviewed' using errcode='55000';
  end if;
  if to_regprocedure('private.erasure_inventory_rows_r7(uuid,uuid[])') is not null
    or to_regprocedure('private.erasure_row_candidates_r7(text,jsonb)') is not null then
    raise exception 'sc_r8_adapter_name_taken' using errcode='55000';
  end if;
  select array_agg(n.nspname||'.'||c.relname order by (n.nspname||'.'||c.relname) collate "C") into actual_tables
    from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname in ('public','private') and c.relkind in ('r','p','f');
  if actual_tables is distinct from (select array_agg(x order by x collate "C") from unnest(r7_tables||step4_tables) x) then
    raise exception 'sc_r8_inventory_gap' using errcode='55000';
  end if;

  create table private.erasure_inventory_baseline_r8 (
    singleton boolean primary key default true check(singleton),
    schema_signature text not null,known_tables text[] not null
  );
  alter table private.erasure_inventory_baseline_r8 enable row level security;
  create trigger immutable_history before update or delete on private.erasure_inventory_baseline_r8
    for each row execute function private.contact_immutable();
  insert into private.erasure_inventory_baseline_r8 values (true,expected,
    r7_tables||step4_tables||array['private.erasure_inventory_baseline_r8']);
end $r8_preflight$;

-- Layered adapters. RENAME keeps each reviewed body, owner and ACL; the
-- wrappers take the same owner, settings and (checked below) the same ACL.
alter function private.erasure_inventory_rows(uuid,uuid[]) rename to erasure_inventory_rows_r7;
alter function private.erasure_row_candidates(text,jsonb) rename to erasure_row_candidates_r7;

create function private.erasure_inventory_rows(tenant uuid,subjects uuid[])
returns table(adapter text,row_key text,row_data jsonb) language sql stable security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
 with apps as (select id from public.applications where company_id=tenant and candidate_id=any(subjects))
 select * from private.erasure_inventory_rows_r7(tenant,subjects)
 union all
 select 'public.application_stage_events',t.id::text,to_jsonb(t) from public.application_stage_events t where t.company_id=tenant and (t.application_id in(select id from apps))
 union all
 select 'public.application_decision_events',t.id::text,to_jsonb(t) from public.application_decision_events t where t.company_id=tenant and (t.application_id in(select id from apps))
 union all
 select 'public.candidate_assessment_note_revisions',t.id::text,to_jsonb(t) from public.candidate_assessment_note_revisions t where t.company_id=tenant and (t.application_id in(select id from apps))
$$;

create function private.erasure_row_candidates(adapter text,data jsonb) returns uuid[]
language plpgsql stable security definer set search_path='' as $$
declare ids uuid[];
begin
 if adapter in ('public.application_stage_events','public.application_decision_events','public.candidate_assessment_note_revisions') then
  select array_agg(distinct a.candidate_id order by a.candidate_id) into ids from public.applications a
   where a.id=(data->>'application_id')::uuid and a.company_id=(data->>'company_id')::uuid;
  if coalesce(cardinality(ids),0)=0 then raise exception using errcode='PT409',message='Unknown candidate dependency';end if;
  return ids;
 end if;
 return private.erasure_row_candidates_r7(adapter,data);
end;$$;

revoke all on function private.erasure_inventory_rows(uuid,uuid[]),private.erasure_row_candidates(text,jsonb) from public,anon,authenticated;

-- Cascade boundary: a Step 4 row may only be deleted inside a purge
-- transaction, and only when its key and hash are in that purge's manifest.
create function private.erasure_step4_cascade_guard() returns trigger
language plpgsql security definer set search_path='' as $$
declare target_adapter text:=tg_table_schema||'.'||tg_table_name;data jsonb:=to_jsonb(old);
begin
 if not exists(select 1 from private.erasure_purge_context where txid=txid_current()) then
  raise exception using errcode='42501',message='Append-only interview history';end if;
 if not exists(
  select 1 from private.erasure_purge_context_rows r where r.txid=txid_current() and r.adapter=target_adapter
   and r.row_key=private.erasure_purge_key(target_adapter,data) and r.row_hash=private.erasure_hash(data) and r.command='delete')
 then raise exception using errcode='42501',message='Purge manifest boundary';end if;
 return old;
end;$$;
revoke all on function private.erasure_step4_cascade_guard() from public,anon,authenticated;
create trigger aa_erasure_cascade_guard before delete on public.application_stage_events
 for each row execute function private.erasure_step4_cascade_guard();
create trigger aa_erasure_cascade_guard before delete on public.application_decision_events
 for each row execute function private.erasure_step4_cascade_guard();
create trigger aa_erasure_cascade_guard before delete on public.candidate_assessment_note_revisions
 for each row execute function private.erasure_step4_cascade_guard();

create policy erasure_read_guard on public.application_stage_events as restrictive for select to authenticated
 using (private.erasure_row_visible('public.application_stage_events',to_jsonb(application_stage_events)));
create policy erasure_read_guard on public.application_decision_events as restrictive for select to authenticated
 using (private.erasure_row_visible('public.application_decision_events',to_jsonb(application_decision_events)));
create policy erasure_read_guard on public.candidate_assessment_note_revisions as restrictive for select to authenticated
 using (private.erasure_row_visible('public.candidate_assessment_note_revisions',to_jsonb(candidate_assessment_note_revisions)));

create or replace function private.erasure_guard_parent_row() returns trigger
language plpgsql security definer set search_path='' as $$
declare subjects uuid[];subject uuid;data jsonb;
begin
 data:=case when tg_op='INSERT' then to_jsonb(new) else to_jsonb(old) end;
 if tg_op='UPDATE' and (to_jsonb(new)->'id' is distinct from data->'id' or to_jsonb(new)->'company_id' is distinct from data->'company_id') then
  raise exception using errcode='PT409',message='Parent identity is immutable';
 end if;
 if tg_table_name='companies' then select array_agg(id order by id) into subjects from public.candidates where company_id=old.id;
 elsif tg_table_name='positions' then
  select array_agg(distinct a.candidate_id order by a.candidate_id) into subjects from public.applications a join public.recruitments r on r.id=a.recruitment_id where r.position_id=old.id;
 elsif tg_table_name='recruitments' then
  select array_agg(distinct candidate_id order by candidate_id) into subjects from public.applications where recruitment_id=old.id;
 elsif tg_table_name in ('assessment_stages','exercise_definition_entries') then
  if tg_op='UPDATE' and (to_jsonb(new)->'recruitment_id' is distinct from data->'recruitment_id' or to_jsonb(new)->'position_id' is distinct from data->'position_id') then
   raise exception using errcode='PT409',message='Parent identity is immutable';
  end if;
  perform private.erasure_assert_row_tenant(data);
  select array_agg(distinct candidate_id order by candidate_id) into subjects from public.applications where recruitment_id=(data->>'recruitment_id')::uuid and company_id=(data->>'company_id')::uuid;
 end if;
 -- SC Step 4 / R8: an assessment stage only cascades into candidate_assessments,
 -- so a stage no candidate assessment uses may be deleted; candidates still lock.
 if tg_op='DELETE' and cardinality(subjects)>0 and (tg_table_name<>'assessment_stages' or exists(
  select 1 from public.candidate_assessments a where a.company_id=(data->>'company_id')::uuid
   and a.recruitment_id=(data->>'recruitment_id')::uuid and a.stage_id=(data->>'id')::uuid))
 then raise exception using errcode='PT409',message='Controlled erasure required';end if;
 foreach subject in array coalesce(subjects,'{}'::uuid[]) loop perform private.erasure_lock_candidate(subject);end loop;
 if tg_op='DELETE' then return old;end if;return new;
end;$$;

comment on table public.application_stage_events is
  'SC-010 R8: candidate-linked audit; erased by FK cascade from the public.applications adapter, listed by the public.application_stage_events adapter.';
comment on table public.application_decision_events is
  'SC-010 R8: candidate-linked personal data (reason); erased by FK cascade from the public.applications adapter, listed by the public.application_decision_events adapter.';
comment on table public.candidate_assessment_note_revisions is
  'SC-010 R8: candidate-linked personal data (interview note versions); erased by FK cascade from the candidate_assessments/applications adapters, listed by the public.candidate_assessment_note_revisions adapter.';
comment on column public.applications.human_decision_reason is
  'SC-010 R8: candidate-linked personal data; erased with its row by the public.applications adapter.';

-- Exact reviewed R7 source bodies, retargeted from R7 to R8 at source level
-- (only the baseline table name differs). CREATE OR REPLACE keeps existing ACLs.
create or replace function public.preview_candidate_erasure(target_candidate uuid,scope_kind text default 'candidate_record',resolution_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
declare tenant uuid;subjects uuid[];p private.candidate_retention_policies;r private.erasure_subject_resolutions;
 baseline private.erasure_inventory_baseline_r8;signature text;counts jsonb:='{}';manifest text;row_digest jsonb:='[]';
 blockers text[]:=array['execution_not_provisioned','external_inventory_unverified','backup_policy_unverified','administrative_inventory_pending_execution'];generated timestamptz:=statement_timestamp();
begin
 select company_id into tenant from public.candidates where id=target_candidate;perform private.erasure_owner(tenant);
 if scope_kind is null or scope_kind not in ('candidate_record','confirmed_subject')
 or (scope_kind='candidate_record' and resolution_id is not null) or (scope_kind='confirmed_subject' and resolution_id is null)
 then raise exception using errcode='PT422',message='Invalid preview scope';end if;
 subjects:=array[target_candidate];
 if scope_kind='confirmed_subject' then
  select * into r from private.erasure_subject_resolutions where id=resolution_id and company_id=tenant and anchor_candidate_id=target_candidate;
  if not found then raise exception using errcode='PT404',message='Resource unavailable';end if;
  subjects:=r.candidate_ids;
  if r.revision<>(select max(revision) from private.erasure_subject_resolutions where company_id=tenant and anchor_candidate_id=target_candidate)
   or r.confirmed_by<>auth.uid() then blockers:=array_append(blockers,'subject_resolution_changed');end if;
  if cardinality(subjects)<>(select count(*) from public.candidates where company_id=tenant and id=any(subjects)) then
   blockers:=array_append(blockers,'subject_resolution_changed');end if;
 else blockers:=array_append(blockers,'subject_resolution_required');end if;
 select * into p from private.candidate_retention_policies where company_id=tenant order by revision desc limit 1;
 if p.id is null then blockers:=array_append(blockers,'retention_policy_required');
 elsif jsonb_array_length(p.rules)<8 then blockers:=array_append(blockers,'retention_policy_incomplete');end if;
 if p.id is not null and p.approved_by<>auth.uid() then blockers:=array_append(blockers,'policy_owner_changed');end if;
 select * into baseline from private.erasure_inventory_baseline_r8 where singleton;
 signature:=private.erasure_schema_signature();
 if baseline.singleton is null or baseline.known_tables is null or signature is distinct from baseline.schema_signature or exists(
  select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','f')
  and not (n.nspname||'.'||c.relname)=any(baseline.known_tables)) then
  blockers:=array_append(blockers,'schema_dependency_unknown');
 else
  -- Preserve the R4-VOICE preview denial as well as its purge/restore adapters.
  -- The legacy R4 fixture has no voice module; SQL in this branch is planned
  -- only when the reviewed voice helper exists.
  if to_regprocedure('private.erasure_voice_request_candidate(uuid,text,uuid)') is not null then
    if exists(select 1 from private.voice_plan_request_keys t where t.company_id=tenant
      and private.erasure_voice_request_candidate(t.company_id,t.operation,t.result_id) is null)
    then blockers:=array_append(blockers,'voice_request_adapter_unknown');end if;
  end if;
  if exists(select 1 from private.contact_requests t where t.company_id=tenant
   and private.erasure_contact_request_candidate(t.company_id,t.operation,t.payload,t.result_id) is null) then blockers:=array_append(blockers,'contact_request_adapter_unknown');end if;
  if exists(select 1 from public.screening_analysis_versions a join public.applications ap on ap.company_id=a.company_id and ap.id=a.application_id
   where ap.company_id=tenant and ap.candidate_id=any(subjects) and a.execution_status in ('pending','processing')) then blockers:=array_append(blockers,'active_screening');end if;
  if exists(select 1 from private.erasure_subject_resolutions sr where sr.company_id=tenant and sr.candidate_ids && subjects and not sr.candidate_ids <@ subjects)
   then blockers:=array_append(blockers,'shared_resolution_requires_adapter');end if;
  with rows as materialized(select * from private.erasure_inventory_rows(tenant,subjects)),
  grouped as(select adapter,count(*) n from rows group by adapter)
  select coalesce((select jsonb_object_agg(adapter,n) from grouped),'{}'::jsonb),
   coalesce((select jsonb_agg(jsonb_build_array(adapter,row_key,private.erasure_hash(row_data)) order by adapter,row_key) from rows),'[]'::jsonb)
  into counts,row_digest;
 end if;
 manifest:=private.erasure_hash(jsonb_build_object('contract','sc010-r1-v1','tenant',tenant,'owner',auth.uid(),'scope',scope_kind,'subjects',subjects,
 'resolution',to_jsonb(r),'current_resolution_revision',(select coalesce(max(revision),0) from private.erasure_subject_resolutions where company_id=tenant and anchor_candidate_id=target_candidate),
 'policy',to_jsonb(p),'schema',signature,'rows',row_digest,'blockers',blockers));
 return jsonb_build_object('scope_kind',scope_kind,'candidate_count',cardinality(subjects),'counts',counts,'blockers',to_jsonb(blockers),
 'policy_revision',coalesce(p.revision,0),'resolution_revision',coalesce(r.revision,0),'manifest_hash',manifest,'schema_signature',signature,
 'generated_at',generated,'expires_at',generated+interval '5 minutes','execution_enabled',false);
end;$$;
create or replace function private.prepare_erasure_purge_manifest(target_request uuid) returns jsonb
language plpgsql volatile security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
declare e private.erasure_executions;digest text;signature text;counts jsonb;baseline text;
begin
 perform private.erasure_check_purge_scope(target_request);
 select * into e from private.erasure_executions where request_id=target_request;
 signature:=private.erasure_schema_signature();
 -- R4 final reviewed baseline is installed by the final migration, never learned at runtime.
 select schema_signature into baseline from private.erasure_inventory_baseline_r8 where singleton;
 if signature is distinct from baseline then raise exception using errcode='PT409',message='Unknown schema dependency';end if;
 select private.erasure_hash(coalesce(jsonb_agg(jsonb_build_array(adapter,row_key,private.erasure_hash(row_data)) order by adapter,row_key),'[]'::jsonb)) into digest from private.erasure_purge_rows(e.company_id,e.candidate_ids);
 insert into private.erasure_purge_manifest
 select target_request,digest,adapter,row_key,private.erasure_hash(row_data) from private.erasure_purge_rows(e.company_id,e.candidate_ids) on conflict do nothing;
 select coalesce(jsonb_object_agg(adapter,n),'{}'::jsonb) into counts from(select adapter,count(*) n from private.erasure_purge_rows(e.company_id,e.candidate_ids) group by adapter)c;
 return jsonb_build_object('manifest_hash',digest,'schema_signature',signature,'counts',counts);
end;$$;
create or replace function private.authorize_retention_suggestion(target_suggestion uuid) returns uuid
language plpgsql volatile security definer set search_path='' set timezone='UTC' set datestyle='ISO, YMD' as $$
declare s private.retention_suggestions;d private.retention_delegations;r private.erasure_subject_resolutions;p jsonb;ticket uuid;result uuid;issued timestamptz;authz jsonb;
begin
 select * into s from private.retention_suggestions where id=target_suggestion for update nowait;
 select * into d from private.retention_delegations where id=s.delegation_id;
 if d.execution_mode<>'automatic' then raise exception using errcode='PT409',message='Automatic delegation required';end if;
 perform private.erasure_execution_gate(false);
 if private.erasure_schema_signature() is distinct from (select schema_signature from private.erasure_inventory_baseline_r8 where singleton) then raise exception using errcode='PT409',message='Unknown schema dependency';end if;
 p:=private.evaluate_retention_subject(s.resolution_id,d.id);
 if p->'blockers'<>'[]'::jsonb or p->>'evidence_hash'<>s.evidence_hash then raise exception using errcode='PT409',message='Retention eligibility changed';end if;
 if exists(select 1 from unnest(s.candidate_ids) x(id) where private.erasure_candidate_frozen(x.id)) then raise exception using errcode='PT409',message='Candidate workflow frozen';end if;
 select * into r from private.erasure_subject_resolutions where id=s.resolution_id;
 -- Fixed graph checks, with unknown schema/JSON/dependencies rejected by the R3 adapter before commit.
 if exists(select 1 from private.contact_requests c where c.company_id=s.company_id and private.erasure_contact_request_candidate(c.company_id,c.operation,c.payload,c.result_id) is null) then raise exception using errcode='PT409',message='Unknown candidate dependency';end if;
 issued:=clock_timestamp();
 insert into private.erasure_preview_tickets(company_id,actor_id,anchor_candidate_id,scope_kind,resolution_id,candidate_ids,manifest_hash,generations,created_at,expires_at)
 values(s.company_id,d.owner_id,r.anchor_candidate_id,'confirmed_subject',r.id,s.candidate_ids,s.evidence_hash,private.erasure_generation_snapshot(s.candidate_ids),issued,issued+interval '5 minutes') returning id into ticket;
 insert into private.erasure_requests(company_id,actor_id,anchor_candidate_id,candidate_ids,scope_kind,preview_ticket_id,manifest_hash,policy_revision,resolution_revision,status,generation)
 values(s.company_id,d.owner_id,r.anchor_candidate_id,s.candidate_ids,'confirmed_subject',ticket,s.evidence_hash,d.policy_revision,r.revision,'authorized',1) returning id into result;
 insert into private.erasure_candidate_lifecycle(candidate_id,company_id,generation,status,request_id)
 select id,s.company_id,1,'frozen',result from unnest(s.candidate_ids) x(id)
 on conflict(candidate_id) do update set generation=erasure_candidate_lifecycle.generation+1,status='frozen',request_id=excluded.request_id;
 authz:=jsonb_build_object('kind','retention_policy','actor_id',d.owner_id,'delegation_id',d.id,'activation_revision',d.revision,'policy_revision',d.policy_revision,'due_generation',s.due_generation,'due_at',s.due_at,'evidence_hash',s.evidence_hash);
 insert into private.retention_authorizations(request_id,authorization_json) values(result,authz);
 update private.retention_suggestions set status='authorized',request_id=result,blockers='[]'::jsonb where id=s.id;
 insert into private.erasure_lifecycle_events(company_id,request_id,actor_id,event,generation) values(s.company_id,result,d.owner_id,'authorized',1);
 -- Reuse the complete reviewed R3 scope validator inside this transaction. This
 -- temporary non-exportable execution never receives a reservation or ledger ACK.
 insert into private.erasure_executions(request_id,company_id,candidate_ids,scope_kind,owner_id,policy_copy,resolution_revision,generation,phase,recovery_retain_until)
 select result,s.company_id,s.candidate_ids,'confirmed_subject',d.owner_id,jsonb_build_object('revision',p2.revision,'rules',p2.rules),r.revision,1,'authorized',clock_timestamp()+interval '1 second'
 from private.candidate_retention_policies p2 where p2.id=d.policy_id;
 perform private.erasure_check_purge_scope(result);
 delete from private.erasure_executions where request_id=result;
 return result;
end;$$;
create or replace function public.get_retention_schedule(target_company uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare d private.retention_delegations;t private.retention_ticks;c private.erasure_execution_config;p private.candidate_retention_policies;schema_ok boolean;begin
 perform private.erasure_owner(target_company);
 select * into d from private.retention_delegations where company_id=target_company order by revision desc limit 1;
 select * into t from private.retention_ticks where company_id=target_company order by created_at desc,id desc limit 1;
 select * into c from private.erasure_execution_config where singleton;
 select * into p from private.candidate_retention_policies where company_id=target_company order by revision desc limit 1;
 schema_ok:=private.erasure_schema_signature() is not distinct from (select schema_signature from private.erasure_inventory_baseline_r8 where singleton);
 return jsonb_build_object('revision',coalesce(d.revision,0),'delegation_id',d.id,'policy_revision',d.policy_revision,'execution_mode',coalesce(d.execution_mode,'suggest_only'),
 'max_batch',coalesce(d.max_batch,25),'revoked',coalesce(d.revoked,true),'owner_current',d.owner_id is not distinct from auth.uid(),
 'authorization_enabled',coalesce(schema_ok and not d.revoked and d.execution_mode='automatic' and d.owner_id=auth.uid() and d.policy_id=p.id and d.policy_revision=p.revision and p.approved_by=auth.uid()
  and c.enabled and c.external_inventory_verified and c.backup_horizon_days is not null and c.artifact_horizon_days is not null and c.retention_margin_days is not null and not c.restore_isolated,false),
 'production_ready',false,
 'blockers',case when c.enabled and c.external_inventory_verified and c.backup_horizon_days is not null and c.artifact_horizon_days is not null and c.retention_margin_days is not null and not c.restore_isolated then '[]'::jsonb else jsonb_build_array('execution_not_provisioned') end || case when schema_ok then '[]'::jsonb else jsonb_build_array('schema_dependency_unknown') end,
 'oldest_pending_at',(select min(created_at) from (select created_at from private.erasure_executions where company_id=target_company and phase in ('authorized','erasing') union all select r.created_at from private.erasure_requests r where r.company_id=target_company and r.status='authorized' and not exists(select 1 from private.erasure_executions e where e.request_id=r.id)) pending),
 'expired_leases',(select count(*) from private.erasure_executions where company_id=target_company and (pending_phase is not null or (phase='erasing' and not local_purged)) and lease_until<clock_timestamp()),
 'last_tick_at',t.created_at,'lag_seconds',case when t.id is null then null else greatest(0,floor(extract(epoch from statement_timestamp()-t.created_at))) end,
 'suggestions',(select count(*) from private.retention_suggestions where company_id=target_company and status='suggested'),
 'authorized',(select count(*) from private.retention_suggestions where company_id=target_company and status='authorized'),
 'blocked',(select count(*) from private.retention_suggestions where company_id=target_company and status='blocked'),
 'holds',(select count(*) from private.erasure_holds where company_id=target_company and released_at is null));
end;$$;


do $r8_postflight$
declare expected text; known text[]; actual_tables text[]; adapter_table text;
begin
  select schema_signature,known_tables into expected,known from private.erasure_inventory_baseline_r8 where singleton;
  if private.erasure_schema_signature() is distinct from expected then
    raise exception 'sc_r8_final_schema_signature_mismatch:%',private.erasure_schema_signature() using errcode='55000';
  end if;
  select array_agg(n.nspname||'.'||c.relname order by (n.nspname||'.'||c.relname) collate "C") into actual_tables
    from pg_class c join pg_namespace n on n.oid=c.relnamespace
    where n.nspname in ('public','private') and c.relkind in ('r','p','f');
  if actual_tables is distinct from (select array_agg(x order by x collate "C") from unnest(known) x) then
    raise exception 'sc_r8_final_inventory_gap' using errcode='55000';
  end if;
  if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private') and p.prosrc ~ 'erasure_inventory_baseline_r[4567]([^0-9]|$)') then
    raise exception 'sc_r8_stale_inventory_reference' using errcode='55000';
  end if;
  if (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname in ('public','private') and p.prosrc like '%erasure_inventory_baseline_r8%'
      and p.proname in ('preview_candidate_erasure','prepare_erasure_purge_manifest','authorize_retention_suggestion','get_retention_schedule')) <> 4 then
    raise exception 'sc_r8_inventory_reference_missing' using errcode='55000';
  end if;
  -- Wrappers: same owner, security and ACL as the reviewed bodies they wrap.
  if exists(select 1 from (values
      ('private.erasure_inventory_rows(uuid,uuid[])'::regprocedure,'private.erasure_inventory_rows_r7(uuid,uuid[])'::regprocedure),
      ('private.erasure_row_candidates(text,jsonb)'::regprocedure,'private.erasure_row_candidates_r7(text,jsonb)'::regprocedure)) v(wrapper,base)
    join pg_proc w on w.oid=v.wrapper join pg_proc b on b.oid=v.base
    where w.proowner<>b.proowner or not w.prosecdef or not b.prosecdef or w.proacl::text is distinct from b.proacl::text) then
    raise exception 'sc_r8_wrapper_acl_mismatch' using errcode='55000';
  end if;
  -- Erasure of Step 4 rows relies on these exact cascades and guards.
  foreach adapter_table in array array['public.application_stage_events','public.application_decision_events','public.candidate_assessment_note_revisions'] loop
    if not exists(select 1 from pg_constraint where conrelid=adapter_table::regclass and contype='f'
        and confrelid='public.applications'::regclass and confdeltype='c')
      or not exists(select 1 from pg_trigger where tgrelid=adapter_table::regclass and tgname='aa_erasure_cascade_guard'
        and tgfoid='private.erasure_step4_cascade_guard()'::regprocedure and tgenabled='O')
      or not exists(select 1 from pg_policy where polrelid=adapter_table::regclass and polname='erasure_read_guard'
        and not polpermissive and polcmd='r' and pg_get_expr(polqual,polrelid) like '%erasure_row_visible%') then
      raise exception 'sc_r8_cascade_contract_changed:%',adapter_table using errcode='55000';
    end if;
  end loop;
end $r8_postflight$

create function private.company_creation_limit()
returns integer language sql immutable set search_path = '' as $$ select 1 $$;
revoke all on function private.company_creation_limit() from public, anon, authenticated;

create or replace function public.create_company(company_name text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  current_user_id uuid := (select auth.uid());
  new_company_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  -- Same lock key as ensure_initial_company: concurrent calls cannot both pass the count.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(current_user_id::text, 0));
  if (select count(*) from public.companies c where c.owner_id = current_user_id)
      >= private.company_creation_limit() then
    raise exception 'Company limit reached' using errcode = 'PT409',
      detail = format('limit=%s', private.company_creation_limit());
  end if;
  insert into public.companies(name, owner_id)
    values (btrim(company_name), current_user_id) returning id into new_company_id;
  insert into public.company_profiles(company_id) values (new_company_id);
  return new_company_id;
end;
$$

-- SC-019 journal: three bulk reasons, every balance change stays journaled.
alter table private.sc19_credit_journal drop constraint sc19_credit_journal_reason_check;
alter table private.sc19_credit_journal add constraint sc19_credit_journal_reason_check
  check (reason in ('trial','paid_grant','analysis_reserve','analysis_release','analysis_retry',
    'bulk_reserve','bulk_release','bulk_transfer'));

create table private.cv_bulk_settings (
  singleton boolean primary key default true check (singleton),
  worker_secret text check (worker_secret is null or octet_length(worker_secret) >= 32),
  max_parallel_company integer not null default 4 check (max_parallel_company between 1 and 20),
  max_parallel_global integer not null default 12 check (max_parallel_global between 1 and 100),
  max_analysis_retries integer not null default 2 check (max_analysis_retries between 0 and 5),
  updated_at timestamptz not null default now()
);
insert into private.cv_bulk_settings(singleton) values (true);

create table private.cv_bulk_batches (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  recruitment_id uuid not null,
  created_by uuid not null references auth.users(id) on delete restrict,
  request_key uuid not null,
  declared_files integer not null check (declared_files between 1 and 100),
  reserved_slots integer not null check (reserved_slots >= 0 and reserved_slots <= declared_files),
  available_before integer not null check (available_before >= 0),
  status text not null default 'uploading' check (status in ('uploading','processing','completed')),
  upload_closed_at timestamptz,
  completed_at timestamptz,
  notify_state text not null default 'pending' check (notify_state in ('pending','sending','sent','failed','skipped')),
  notify_attempts integer not null default 0 check (notify_attempts between 0 and 10),
  notify_lease_until timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (company_id, id),
  unique (company_id, request_key),
  foreign key (company_id, recruitment_id) references public.recruitments(company_id, id) on delete cascade,
  check ((status = 'completed') = (completed_at is not null))
);
create index cv_bulk_batches_recruitment_idx on private.cv_bulk_batches(company_id, recruitment_id, created_at desc);
create index cv_bulk_batches_open_idx on private.cv_bulk_batches(status, updated_at) where status <> 'completed' or notify_state in ('pending','sending');

create table private.cv_bulk_items (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null,
  batch_id uuid not null,
  position integer not null check (position between 1 and 100),
  file_name text check (file_name is null or length(file_name) between 1 and 255),
  file_kind text not null check (file_kind in ('pdf','docx','txt','image','other')),
  file_bytes integer not null check (file_bytes >= 0),
  phase text not null check (phase in ('awaiting_upload','queued','analyzing','done','error')),
  error_reason text check (error_reason is null or error_reason in (
    'over_limit','unreadable_scan','protected_pdf','bad_format','too_large','no_text','duplicate',
    'not_uploaded','analysis_failed','not_eligible')),
  slot_state text not null check (slot_state in ('none','held','transferred','released')),
  ocr_used boolean not null default false,
  name_detected boolean not null default false,
  candidate_id uuid,
  application_id uuid,
  duplicate_of_application uuid,
  analysis_id uuid,
  analysis_retries integer not null default 0 check (analysis_retries between 0 and 5),
  dispatched_at timestamptz,
  input_tokens bigint check (input_tokens is null or input_tokens >= 0),
  output_tokens bigint check (output_tokens is null or output_tokens >= 0),
  cached_input_tokens bigint check (cached_input_tokens is null or cached_input_tokens >= 0),
  cost_amount numeric(12,6) check (cost_amount is null or cost_amount >= 0),
  cost_currency text check (cost_currency is null or cost_currency ~ '^[A-Z]{3}$'),
  pricing_version text check (pricing_version is null or length(pricing_version) between 1 and 80),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (batch_id, position),
  foreign key (company_id, batch_id) references private.cv_bulk_batches(company_id, id) on delete cascade,
  foreign key (company_id, candidate_id) references public.candidates(company_id, id) on delete cascade,
  foreign key (application_id) references public.applications(id) on delete cascade,
  foreign key (duplicate_of_application) references public.applications(id) on delete cascade,
  foreign key (analysis_id) references public.screening_analysis_versions(id) on delete set null,
  check ((phase = 'error') = (error_reason is not null)),
  check (phase not in ('queued','analyzing','done') or (candidate_id is not null and application_id is not null)),
  check (phase <> 'analyzing' or analysis_id is not null),
  check (slot_state <> 'held' or phase in ('awaiting_upload','queued')),
  check (error_reason is distinct from 'duplicate' or slot_state in ('released','none'))
);
create index cv_bulk_items_phase_idx on private.cv_bulk_items(company_id, phase);
create index cv_bulk_items_candidate_idx on private.cv_bulk_items(company_id, candidate_id) where candidate_id is not null;
create index cv_bulk_items_application_idx on private.cv_bulk_items(application_id) where application_id is not null;

-- Proposal groups for any application (bulk or single), one row per application.
create table private.application_preselection_groups (
  id uuid not null default gen_random_uuid() unique,
  application_id uuid primary key references public.applications(id) on delete cascade,
